231	int MixedStreamerReducer::dump(const IndexDumper::Pointer &dumper) {
232	  LOG_INFO("Begin brute force reducer dump");
233	
234	  if (state_ != STATE_REDUCE) {
235	    LOG_WARN("Reduce first before dump");
236	    return IndexError_NoReady;
237	  }
238	
239	  ailego::ElapsedTime timer;
240	  int ret = 0;
241	  if (target_builder_ != nullptr) {
242	    target_builder_->dump(dumper);
243	  } else {
244	    target_streamer_->dump(dumper);
245	  }
246	  if (ret == IndexError_NotImplemented) {
247	    LOG_WARN("Dump index not implemented");
248	  } else if (ret < 0) {
249	    LOG_ERROR("Failed to dump in streamer");
250	  }
251	
252	  return ret;
253	}
