255	int MixedStreamerReducer::read_vec(size_t source_streamer_index,
256	                                   const IndexProvider::Pointer &provider,
257	                                   const IndexFilter &filter,
258	                                   const uint32_t id_offset,
259	                                   uint32_t *next_id) {
260	  const auto &streamer = streamers_[source_streamer_index];
261	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
262	  const IndexQueryMeta source_streamer_query_meta{streamer->meta().data_type(),
263	                                                  streamer->meta().dimension()};
264	
265	  bool need_revert = (target_streamer_->meta().reformer_name() !=
266	                          streamer->meta().reformer_name() &&
267	                      reformer != nullptr);
268	  if (target_builder_ && reformer) {
269	    need_revert = true;
270	  }
271	
272	  if (!provider) {
273	    LOG_ERROR("Source provider is null, index=%zu", source_streamer_index);
274	    return IndexError_Runtime;
275	  }
276	  IndexProvider::Iterator::Pointer iterator = provider->create_iterator();
277	  if (!iterator) {
278	    LOG_ERROR("Failed to create source provider iterator, index=%zu",
279	              source_streamer_index);
280	    return IndexError_Runtime;
281	  }
282	
283	  while (iterator->is_valid()) {
284	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
285	      LOG_DEBUG("read_vec cancelled.");
286	      return 0;
287	    }
288	    if (filter(iterator->key() + (uint64_t)id_offset)) {
289	      (*stats_.mutable_filtered_count())++;
290	      iterator->next();
291	      continue;
292	    }
293	
294	    const void *vector_data = iterator->data();
295	    if (!vector_data) {
296	      LOG_ERROR("Failed to read source vector, index=%zu key=%zu",
297	                source_streamer_index, static_cast<size_t>(iterator->key()));
298	      return IndexError_ReadData;
299	    }
300	
301	    std::vector<uint8_t> bytes;
302	    if (need_revert) {
303	      std::string new_vector;
304	      if (reformer->revert(vector_data, source_streamer_query_meta,
305	                           &new_vector) != 0) {
306	        LOG_ERROR("Failed to revert the vector");
307	        return IndexError_Runtime;
308	      }
309	      bytes.resize(new_vector.size());
310	      memcpy(bytes.data(), new_vector.data(), bytes.size());
311	    } else {
312	      // TODO: eliminate the copy
313	      bytes.resize(provider->element_size());
314	      memcpy(bytes.data(), vector_data, bytes.size());
315	    }
316	
317	    // TODO: use id instead of key
318	    if (!mt_list_.produce(VectorItem((*next_id)++, std::move(bytes)))) {
319	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
320	                (size_t)iterator->key());
321	      return IndexError_Runtime;
322	    }
323	    iterator->next();
324	  }
325	  return 0;
326	}
327	
328	void MixedStreamerReducer::add_vec(int *result) {
329	  if (target_builder_ != nullptr) {
330	    add_vec_with_builder(result);
331	    return;
332	  }
333	  ailego::ElapsedTime timer;
334	  auto target_streamer_context = target_streamer_->create_context();
335	  auto target_streamer_query_meta = IndexQueryMeta{
336	      IndexMeta::MetaType::MT_DENSE, target_streamer_->meta().data_type(),
337	      target_streamer_->meta().dimension()};
338	  const bool need_convert = (!is_target_and_source_same_reformer_) &&
339	                            target_streamer_reformer_ != nullptr;
340	
341	  AILEGO_DEFER([&]() {
342	    // make producer quit
343	    mt_list_.done();
344	  });
345	
346	  VectorItem vector_item;
347	  while (mt_list_.consume(&vector_item)) {
348	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
349	      LOG_DEBUG("add_vec cancelled.");
350	      return;
351	    }
352	
353	    const void *vector = vector_item.vec_.data();
354	    std::string new_vector;
355	
356	
357	    if (need_convert) {
358	      IndexQueryMeta new_meta;
359	      if (target_streamer_reformer_->convert(vector, original_query_meta_,
360	                                             &new_vector, &new_meta) != 0) {
361	        LOG_ERROR("Failed to transform vector");
362	        *result = IndexError_Runtime;
363	        return;
364	      }
365	      vector = new_vector.data();
366	    }
367	    // 1. no reformer: target_streamer_query_meta_ = original_query_meta_
368	    // 2. has reformer, matched(need_convert = false): use
369	    // target_streamer_query_meta_
370	    // 3. has reformer, not matched(need_convert = true): use
371	    // target_streamer_query_meta_
372	
373	
374	    // TODO: use id instead of key
375	    int ret = target_streamer_->add_with_id_impl(
376	        (uint32_t)vector_item.pkey_, vector, target_streamer_query_meta,
377	        target_streamer_context);
378	    if (ret != 0) {
379	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
380	                ret, IndexError::What(ret), (size_t)vector_item.pkey_);
381	      *result = ret;
382	      return;
383	    }
384	  }
385	
386	  *result = 0;
387	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
388	  return;
389	}
390	
391	void MixedStreamerReducer::add_vec_with_builder(int *result) {
392	  ailego::ElapsedTime timer;
393	
394	  AILEGO_DEFER([&]() {
395	    // make producer quit
396	    mt_list_.done();
397	  });
398	
399	  VectorItem vector_item;
400	  while (mt_list_.consume(&vector_item)) {
401	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
402	      LOG_DEBUG("add_vec cancelled.");
403	      return;
404	    }
405	
406	    const void *vector = vector_item.vec_.data();
407	    std::string out_vector_buffer = std::string(
408	        static_cast<const char *>(vector),
409	        original_query_meta_.dimension() * original_query_meta_.unit_size());
410	    PushToDocCache(original_query_meta_, (uint32_t)vector_item.pkey_,
411	                   out_vector_buffer);
412	  }
413	
414	  *result = 0;
415	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
416	  return;
417	}
418	
419	void MixedStreamerReducer::add_sparse_vec(int *result) {
420	  ailego::ElapsedTime timer;
421	  auto target_streamer_context = target_streamer_->create_context();
422	  auto target_streamer_query_meta = IndexQueryMeta{
423	      IndexMeta::MetaType::MT_SPARSE,
424	      target_streamer_->meta().data_type(),
425	  };
426	
427	  auto need_convert = !is_target_and_source_same_reformer_ &&
428	                      target_streamer_reformer_ != nullptr;
429	
430	  AILEGO_DEFER([&]() {
431	    // make producer quit
432	    sparse_mt_list_.done();
433	  });
434	
435	  SparseVectorItem sparse_vector_item;
436	  while (sparse_mt_list_.consume(&sparse_vector_item)) {
437	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
438	      LOG_DEBUG("add_sparse_vec cancelled.");
439	      return;
440	    }
441	    auto sparse_count = sparse_vector_item.sparse_indices_.size();
442	    auto indices = sparse_vector_item.sparse_indices_.data();
443	    auto values = sparse_vector_item.sparse_values_.data();
444	
445	    std::string converted_sparse_values_buffer;
446	    if (need_convert) {
447	      IndexQueryMeta new_meta;
448	      if (target_streamer_reformer_->convert(
449	              sparse_count, indices, values, original_query_meta_,
450	              &converted_sparse_values_buffer, &new_meta) != 0) {
451	        LOG_ERROR("Failed to transform vector");
452	        *result = IndexError_Runtime;
453	        return;
454	      }
455	      values = converted_sparse_values_buffer.data();
456	      target_streamer_query_meta = new_meta;
457	    }
458	
459	    // TODO: use id instead of key
460	    int ret = target_streamer_->add_with_id_impl(
461	        (uint32_t)sparse_vector_item.pkey_, sparse_count, indices, values,
462	        target_streamer_query_meta, target_streamer_context);
463	    if (ret != 0) {
464	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
465	                ret, IndexError::What(ret), (size_t)sparse_vector_item.pkey_);
466	      *result = ret;
467	      return;
468	    }
469	  }
470	
471	  *result = 0;
472	  LOG_DEBUG("add_sparse_vec. cost time: [%zu]s", (size_t)timer.seconds());
473	  return;
474	}
