31	      params.get_as_bool(PARAM_MIXED_STREAMER_REDUCER_ENABLE_PK_REWRITE);
32	  params.get(PARAM_MIXED_STREAMER_REDUCER_NUM_OF_ADD_THREADS,
33	             &num_of_add_threads_);
34	  if (num_of_add_threads_ <= 0) {
35	    LOG_ERROR("Wrong parameter. %s must be set greater than 0.",
36	              PARAM_MIXED_STREAMER_REDUCER_NUM_OF_ADD_THREADS.c_str());
37	    return IndexError_InvalidArgument;
38	  }
39	
40	  params_ = params;
41	
42	  state_ = STATE_INITED;
