476	
477	int MixedStreamerReducer::read_sparse_vec(size_t source_streamer_index,
478	                                          const IndexFilter &filter,
479	                                          const uint32_t id_offset,
480	                                          uint32_t *next_id) {
481	  const auto &streamer = streamers_[source_streamer_index];
482	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
483	  const bool need_revert =
484	      !is_target_and_source_same_reformer_ && reformer != nullptr;
485	
486	  IndexStreamer::SparseProvider::Pointer provider =
487	      streamer->create_sparse_provider();
488	  IndexStreamer::SparseProvider::Iterator::Pointer iterator =
489	      provider->create_iterator();
490	
491	  while (iterator->is_valid()) {
492	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
493	      LOG_DEBUG("read_sparse_vec cancelled.");
494	      return 0;
495	    }
496	    if (filter(iterator->key() + (uint64_t)id_offset)) {
497	      (*stats_.mutable_filtered_count())++;
498	      iterator->next();
499	      continue;
500	    }
501	
502	    auto sparse_count = iterator->sparse_count();
503	    std::vector<uint32_t> sparse_indices(sparse_count);
504	    std::string sparse_values;
505	
506	    if (need_revert) {
507	      std::string new_sparse_values;
508	      if (reformer->revert(iterator->sparse_count(), iterator->sparse_indices(),
509	                           iterator->sparse_data(),
510	                           {
511	                               IndexMeta::MetaType::MT_SPARSE,
512	                               streamer->meta().data_type(),
513	                           },
514	                           &new_sparse_values) != 0) {
515	        LOG_ERROR("Failed to revert the sparse vector");
516	        return IndexError_Runtime;
517	      }
518	      sparse_values = std::move(new_sparse_values);
519	    } else {
520	      sparse_values.resize(sparse_count * streamer->meta().unit_size());
521	      memcpy(sparse_values.data(), iterator->sparse_data(),
522	             sparse_values.size());
523	    }
524	
525	    // TODO: eliminate the copy
526	    memcpy(sparse_indices.data(), iterator->sparse_indices(),
527	           sparse_indices.size() * sizeof(uint32_t));
528	
529	    // TODO: use id instead of key
530	    if (!sparse_mt_list_.produce(SparseVectorItem((*next_id)++,
531	                                                  std::move(sparse_indices),
532	                                                  std::move(sparse_values)))) {
533	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
534	                (size_t)iterator->key());
535	      return IndexError_Runtime;
536	    }
537	    iterator->next();
538	  }
539	  return 0;
540	}
541	
542	void MixedStreamerReducer::PushToDocCache(const IndexQueryMeta &meta,
543	                                          uint32_t doc_id, std::string &doc) {
544	  std::lock_guard<std::mutex> lock(mutex_);
545	  while (doc_cache_.size() <= doc_id) {
546	    std::string fake_data(meta.dimension() * meta.unit_size(), 0);
547	    doc_cache_.push_back(std::make_pair(kInvalidKey, fake_data));
548	  }
549	  doc_cache_[doc_id] = std::make_pair(doc_id, doc);
550	}
551	
552	int MixedStreamerReducer::IndexBuild() {
553	  IndexHolder::Pointer target_holder;
554	  if (original_query_meta_.data_type() == core::IndexMeta::DataType::DT_FP16) {
555	    auto holder = std::make_shared<
556	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_FP16>>(
557	        original_query_meta_.dimension());
558	    for (auto doc : doc_cache_) {
559	      ailego::NumericalVector<uint16_t> vec(doc.second);
560	      if (doc.first == kInvalidKey) {
561	        continue;
562	      }
563	      if (!holder->emplace(doc.first, vec)) {
564	        LOG_ERROR("Failed to add vector");
565	        return core::IndexError_Runtime;
566	      }
567	    }
568	    target_holder = holder;
569	  } else if (original_query_meta_.data_type() ==
570	             core::IndexMeta::DataType::DT_FP32) {
571	    auto holder = std::make_shared<
572	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_FP32>>(
573	        original_query_meta_.dimension());
574	    for (auto doc : doc_cache_) {
575	      ailego::NumericalVector<float> vec(doc.second);
576	      if (doc.first == kInvalidKey) {
577	        continue;
578	      }
579	      if (!holder->emplace(doc.first, vec)) {
580	        LOG_ERROR("Failed to add vector");
581	        return core::IndexError_Runtime;
582	      }
583	    }
584	    target_holder = holder;
585	  } else if (original_query_meta_.data_type() ==
586	             core::IndexMeta::DataType::DT_INT8) {
587	    auto holder = std::make_shared<
588	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_INT8>>(
589	        original_query_meta_.dimension());
590	    for (auto doc : doc_cache_) {
591	      ailego::NumericalVector<uint8_t> vec(doc.second);
592	      if (doc.first == kInvalidKey) {
593	        continue;
594	      }
595	      if (!holder->emplace(doc.first, vec)) {
596	        LOG_ERROR("Failed to add vector");
597	        return core::IndexError_Runtime;
598	      }
599	    }
600	    target_holder = holder;
601	  } else {
602	    LOG_ERROR("data_type is not support");
603	    return core::IndexError_Runtime;
604	  }
605	  if (target_builder_converter_) {
606	    core::IndexConverter::TrainAndTransform(target_builder_converter_,
607	                                            target_holder);
608	    target_holder = target_builder_converter_->result();
609	  }
610	  int ret = target_builder_->train(target_holder);
611	  if (ret != 0) {
612	    LOG_ERROR("Failed to train target builder, ret=%d", ret);
613	    return ret;
614	  }
615	  ret = target_builder_->build(target_holder);
616	  if (ret != 0) {
617	    LOG_ERROR("Failed to build target index, ret=%d", ret);
618	    return ret;
619	  }
620	  return 0;
621	}
622	
623	INDEX_FACTORY_REGISTER_STREAMER_REDUCER_ALIAS(MixedStreamerReducer,
624	                                              MixedStreamerReducer);
